/** Lays a model whose long axis runs along Z back onto the vertical, keeping the
 *  default three-quarter turn so it is not seen dead-on. Use `_Z` when the top
 *  of the subject sits at +Z, and `_NEG_Z` when it sits at −Z — the generated
 *  figures lie head-first down the negative axis. */
const UPRIGHT_FROM_Z: [number, number, number] = [-Math.PI / 2, -0.28, 0];
/** Unused today — every Z-long model in the library currently lies the other way.
 *  Kept as the documented counterpart so the next one doesn't get a hand-rolled
 *  literal, which is how a figure ends up upside down. */
export const UPRIGHT_FROM_NEG_Z: [number, number, number] = [Math.PI / 2, -0.28, 0];

/** The five illustration slots the UI draws from. */
export type ArtAsset = "thumb" | "organ" | "microscopic" | "compare" | "location";

export type Hotspot = {
  id: string;
  label: string;
  /** The 2–5 word line shown in the callout. */
  detail: string;
  /** A paragraph on what this part is and why it matters, opened from the
   *  callout. Optional so a hotspot can exist before its text is written. */
  body?: string;
  position: [number, number, number];
  color: string;
};

export type Organ = {
  id: OrganId;
  name: string;
  scientificName: string;
  system: string;
  /** Omitted while a specimen is still being produced. The viewer shows a
   *  placeholder rather than hiding the organ — the library is the syllabus, so
   *  a learner should see every structure whether or not its model exists yet. */
  model?: string;
  icon: string;
  accent: string;
  /** Definite article — "le" | "la" | "l'" | "les". Stored rather than derived:
   *  elision has exceptions (h aspiré) that a rule would get wrong. */
  article: string;
  /** Contracted "de" — "du" | "de la" | "de l'" | "des". */
  de: string;
  description: string;
  poetic: string;
  size: string;
  weight: string;
  /** Label for the second measurement row, which defaults to "Poids". A ureter's
   *  mass is not a fact anyone teaches, so the row carries its calibre instead —
   *  and must then say "Calibre", not claim 3 mm is a weight. Set this whenever
   *  `weight` holds something that is not a mass. */
  weightLabel?: string;
  location: string;
  function: string;
  dailyFact: string;
  medical: string;
  bloodSupply: string;
  /** A single memorable line, surfaced as the "Le saviez-vous" note. */
  funFact: string;
  tissue: string;
  comparison: string;
  conditions: string[];
  hotspots: Hotspot[];
  /** Whether the full `/anatomy/<id>/*.webp` set exists. Kept for organs that
   *  ship every slot; `illustrations` overrides it for partial sets. */
  illustrated: boolean;
  /** Which illustration slots actually exist, for organs that have some but not
   *  all. A missing slot falls back to the accent glyph rather than a broken
   *  image, so artwork can land one piece at a time. */
  illustrations?: ArtAsset[];
  /** Resting pivot rotation in radians. Generated models arrive on arbitrary
   *  axes — a model whose long axis runs along Z points at the camera and reads
   *  as foreshortened. Omit to use the default three-quarter turn. */
  rotation?: [number, number, number];
};

/** The display `name` is capitalised for the library rail and the `h1`. Inside a
 *  sentence French wants it lowercase — "Le cœur", not "Le Cœur". Only the first
 *  letter is folded, so "Bouche et mâchoire" keeps any internal capitals. */
const lower = (name: string) => name.charAt(0).toLowerCase() + name.slice(1);

/** "Le cœur", "L'œil", "Les poumons" — sentence-initial, no space after `l'`. */
export const withArticle = (o: Organ) =>
  `${o.article}${o.article.endsWith("’") ? "" : " "}${lower(o.name)}`;

/** "du cœur", "de l'œil", "des poumons" — mid-sentence, fully lowercase. */
export const ofOrgan = (o: Organ) =>
  `${o.de}${o.de.endsWith("’") ? "" : " "}${lower(o.name)}`;

/**
 * Folds a string for accent-insensitive search, so typing "coeur" or "oesophage"
 * finds "cœur" and "œsophage". Ligatures are expanded *before* NFD because œ and
 * æ have no canonical decomposition — normalising first would leave them intact.
 */
export const fold = (s: string) =>
  s
    .replace(/œ/gi, "oe")
    .replace(/æ/gi, "ae")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase();

